import {clinics,specialties,professionals,clinic,specialty,professional,dates,dateObject,dateLabel,timeLabel,availableTimes,localISO,syntheticSessions} from './data.js';
export const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dataLocalDateTime=()=>{const now=new Date();return localISO(now)+'T'+String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');};
const paths={
 palm:'<path d="M6 14V8a1.5 1.5 0 0 1 3 0v4-7a1.5 1.5 0 0 1 3 0v7-6a1.5 1.5 0 0 1 3 0v7-4a1.5 1.5 0 0 1 3 0v7c0 5-3 7-7 7-3 0-5-2-7-5l-2-3a1.5 1.5 0 0 1 2-2l3 2"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m14 6-6 6 6 6"/>',next:'<path d="m9 6 6 6-6 6"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',
 text:'<path d="M4 5h16M12 5v15m-5 0h10"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',chart:'<path d="M4 4v17h17M8 15v3m5-8v8m5-13v13"/>',
 offline:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0m-3 4h.01M3 3l18 18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>'
};
export const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.info}</svg>`;
export const brand=()=>`<a class="brand" href="#home" aria-label="Saúde na Palma da Mão, início"><span class="symbol">${icon('palm')}</span><span><b>saúde</b><small>na palma da mão</small></span></a>`;
export const button=(text,action,kind='',attrs='')=>`<button class="button ${kind}" type="button" data-action="${action}" ${attrs}>${text}</button>`;
export const link=(text,route,kind='')=>`<a class="button ${kind}" href="#${route}">${text}</a>`;
export const heading=(text,sub='')=>`<div class="page-title"><h1>${text}</h1>${sub?`<p>${sub}</p>`:''}</div>`;
export const notice=text=>`<div class="notice">${icon('info')}<p>${text}</p></div>`;
export const context=text=>`<div class="context">${icon('pin')}<span>${e(text)}</span></div>`;
export const step=(n,label)=>`<div class="step"><div class="step-label"><span>AGENDAMENTO</span><span>${n} de 4 · ${label}</span></div><div class="tracks" aria-hidden="true">${[1,2,3,4].map(x=>`<i class="${x<=n?'filled':''}"></i>`).join('')}</div></div>`;
export const formError=()=>'<div class="form-error" id="form-error" role="alert"></div>';
export function field(id,label,{type='text',value='',placeholder='',hint='',auto='',required=true,min='',max=''}={}){
 const password=type==='password';
 return `<div class="field"><label for="${id}">${label}</label><div class="${password?'input-wrap':''}"><input id="${id}" name="${id}" type="${type}" value="${e(value)}" placeholder="${e(placeholder)}" ${required?'required':''} ${auto?`autocomplete="${auto}"`:''} ${type==='tel'?'inputmode="tel" maxlength="16"':''} ${min?`min="${min}"`:''} ${max?`max="${max}"`:''} ${hint?`aria-describedby="${id}-hint"`:''}>${password?`<button class="show-password" type="button" data-action="password" data-input="${id}" aria-label="Mostrar senha">${icon('eye')}</button>`:''}</div>${hint?`<p class="hint" id="${id}-hint">${hint}</p>`:''}<p class="field-error" id="${id}-error" hidden></p></div>`;
}
const ratioLabel=(n,total)=>total?`${n}/${total} · ${(n/total*100).toFixed(1).replace('.',',')}%`:'Sem sessões';
const radio=selected=>`<span class="radio" aria-hidden="true">${selected?icon('check'):''}</span>`;
function choice({id,name,sub,meta='',selected,action,initials=''}){return `<button class="choice" type="button" data-action="${action}" data-id="${e(id)}" aria-pressed="${selected}">${initials?`<span class="avatar" aria-hidden="true">${e(initials)}</span>`:''}<span class="copy"><strong>${e(name)}</strong><span class="sub">${e(sub)}</span>${meta?`<span class="meta">${e(meta)}</span>`:''}</span>${radio(selected)}</button>`;}
export function clinicResults(query,draft){
 const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
 const results=clinics.filter(c=>(c.name+' '+c.district).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));
 return {count:results.length,html:results.length?`<div class="choices">${results.map(c=>choice({id:c.id,name:c.name,sub:`${c.district} · ${c.city}`,meta:c.access,selected:draft.clinicId===c.id,action:'clinic'})).join('')}</div>`:`<div class="empty"><span class="empty-symbol">${icon('search')}</span><h2>Nenhuma clínica encontrada.</h2><p>Confira o nome ou tente buscar por outro bairro.</p>${button('Ver todas as clínicas','clear-search','secondary')}</div>`};
}
export function summary(b){return `<dl class="summary"><div><dt>Clínica</dt><dd>${e(clinic(b.clinicId)?.name)}<small>${e(clinic(b.clinicId)?.district)}, Recife</small></dd></div><div><dt>Atendimento</dt><dd>${e(specialty(b.specialtyId)?.name)}<small>${e(professional(b.professionalId)?.name)}</small></dd></div><div><dt>Data e horário</dt><dd class="date-value">${e(dateLabel(b.date))}<small>às <b>${e(timeLabel(b.time))}</b></small></dd></div></dl>`;}
export function appointment(b){const d=dateObject(b.date);return `<div class="appointment"><div class="calendar-block"><span>${d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}</span><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','').toUpperCase()}</span></div><div class="appointment-text"><strong>${e(specialty(b.specialtyId)?.name)}</strong><span>${e(dateLabel(b.date,true))} · ${e(timeLabel(b.time))}</span><span>${e(professional(b.professionalId)?.name)}</span></div></div>`;}
const navItems=[['home','home','Início'],['appointments','calendar','Consultas'],['account','user','Conta']];
export function shell(s,body){
 const primary=['home','welcome','appointments','account','dashboard','settings','about','install','legal'].includes(s.route);
 const active=s.route==='appointments'||s.route.startsWith('detail/')?'appointments':s.route==='account'||s.route==='edit-profile'?'account':'home';
 const links=navItems.map(([r,i,label])=>`<a href="#${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');
 const installOffer=!s.installed&&['welcome','home'].includes(s.route)?`<button class="install-callout" type="button" data-action="install-entry" aria-label="Instalar aplicativo">${icon('download')}<span><strong>Instalar aplicativo</strong><small>Abra direto pela tela inicial.</small></span>${icon('next')}</button>`:'';
 const flow=['clinic','specialty','professional','time','review'].includes(s.route);
 const d=s.draft;
 const aside=flow&&d.clinicId?`<aside class="itinerary" aria-label="Resumo das suas escolhas"><div class="eyebrow">SUAS ESCOLHAS</div><h2>Um passo<br>de cada vez.</h2><dl><dt>Clínica</dt><dd>${e(clinic(d.clinicId)?.name)}</dd>${d.specialtyId?`<dt>Atendimento</dt><dd>${e(specialty(d.specialtyId)?.name)}</dd>`:''}${d.professionalId?`<dt>Profissional</dt><dd>${e(professional(d.professionalId)?.name)}</dd>`:''}${d.date?`<dt>Dia</dt><dd>${e(dateLabel(d.date,true))}</dd>`:''}${d.time?`<dt>Horário</dt><dd>${e(timeLabel(d.time))}</dd>`:''}</dl><p class="hint">Você pode voltar e conferir suas escolhas antes de confirmar.</p></aside>`:'';
 return `<div class="app-shell"><aside class="side">${brand()}<nav aria-label="Navegação principal">${s.user?links:`<a href="#welcome">${icon('home')}Apresentação</a><a href="#login">${icon('user')}Entrar na conta</a>`}<a href="#settings">${icon('text')}Ajustar leitura</a>${!s.installed?`<a href="#install" class="${s.route==='install'?'active':''}" ${s.route==='install'?'aria-current="page"':''}>${icon('download')}Instalar aplicativo</a>`:''}</nav><div class="side-bottom"><a href="#about">Sobre o projeto</a><a href="#dashboard">Painel do projeto</a><p>Projeto acadêmico.<br>${s.remote?'Conta online no servidor.':'Demonstração neste navegador.'}</p></div></aside><div class="shell-content"><div class="demo-strip"><span>PROJETO ACADÊMICO · AGENDA FICTÍCIA</span><a href="#about">Entenda</a></div>${!navigator.onLine?`<div class="connection">${icon('offline')}<span>${s.remote?'Sem internet · alterações na conta online indisponíveis':'Sem internet · demonstração local disponível'}</span></div>`:''}<header class="topbar">${primary?brand():`<button class="back" type="button" data-action="back">${icon('back')}Voltar</button>`}<button class="plain" type="button" data-action="read-settings" aria-label="Ajustar leitura">${icon('text')}<span>Ajustar leitura</span></button></header><div class="content-and-aside ${aside?'with-aside':''}"><main id="main" class="main ${s.route==='dashboard'?'wide':''}" tabindex="-1">${installOffer}${body}</main>${aside}</div>${s.user?`<nav class="bottom-nav" aria-label="Navegação principal no celular">${links}</nav>`:''}</div></div>`;
}
function baseView(s){
 const d=s.draft,u=s.user;
 switch(s.route){
 case 'welcome':return `<div class="welcome"><div class="eyebrow">SEU CUIDADO, NO SEU TEMPO</div><h1>Sua próxima consulta,<br>com mais clareza.</h1><p class="intro">Escolha o atendimento, encontre um horário e acompanhe suas consultas em um só lugar.</p><div class="welcome-flow"><div class="welcome-task">${icon('search')}Escolha uma clínica e um profissional.</div><div class="welcome-task">${icon('calendar')}Reserve um horário na agenda fictícia.</div><div class="welcome-task">${icon('check')}Confira, reagende ou cancele quando precisar.</div></div><div class="actions">${button('Explorar demonstração','demo')}${link('Entrar na minha conta','login','secondary')}${link('Criar uma conta neste navegador','register','text')}</div><p class="local-note">Esta é uma demonstração acadêmica. Não marca consultas reais. Seus dados ficam neste navegador.</p></div>`;
 case 'home':{
  const next=s.bookings.find(b=>b.status==='scheduled'&&`${b.date}T${b.time}`>=(dataLocalDateTime()));
  return `<div class="eyebrow">SEU CUIDADO, NO SEU TEMPO</div><h1 class="home-title">Olá,<br><em>${e(u.name.split(' ')[0])}.</em></h1><p class="intro">Vamos cuidar da sua<br>próxima consulta?</p><button class="big-action" type="button" data-action="new-booking" aria-label="Agendar uma consulta">${icon('calendar')}<span><strong>Agendar uma consulta</strong><small>Escolha onde e quando.</small></span></button><div class="section-title"><h2>Sua próxima consulta</h2></div>${next?`${appointment(next)}<a class="row-link" href="#detail/${next.id}">Ver detalhes da consulta</a>`:`<div class="empty"><p>Você ainda não tem uma consulta marcada. Escolha um atendimento para começar.</p></div>`}<div class="read-help">${icon('text')}<span>Prefere letras maiores?</span><a href="#settings">Ajustar leitura</a></div><p class="local-note">${u.demo?'Você está usando o perfil de demonstração.':'Conta salva neste navegador.'} Agenda fictícia para o projeto.</p>`;
 }
 case 'login':return heading('Entre na sua conta.','Use o telefone e a senha cadastrados neste navegador.')+`<form id="login-form" novalidate>${formError()}${field('phone','Telefone',{type:'tel',auto:'tel',placeholder:'(81) 99999-9999'})}${field('password','Senha',{type:'password',auto:'current-password'})}<a class="text-link" href="#recover">Esqueci minha senha</a><div class="actions"><button class="button" type="submit">Entrar na minha conta</button>${button('Explorar demonstração','demo','secondary')}</div></form><div class="separated"><p>Ainda não tem uma conta?</p>${link('Criar minha conta','register','secondary')}</div>`;
 case 'register':return heading('Vamos criar<br>sua conta.','O cadastro funciona neste navegador, inclusive sem internet.')+`<form id="register-form" novalidate>${formError()}${field('name','Nome completo',{auto:'name',placeholder:'Como você se chama?'})}${field('phone','Telefone',{type:'tel',auto:'tel',placeholder:'(81) 99999-9999'})}${field('birth','Data de nascimento',{type:'date',auto:'bday',max:localISO()})}${field('password','Crie uma senha',{type:'password',auto:'new-password',hint:'Use pelo menos 8 caracteres.'})}<label class="check-label"><input type="checkbox" id="terms" name="terms"><span>Li e concordo com os <a href="#legal">Termos da demonstração e o aviso de privacidade</a>.</span></label><div class="actions"><button class="button" type="submit">Criar minha conta</button></div></form>`;
 case 'backup':return `<span class="success-icon">${icon('check')}</span>`+heading('Sua conta está pronta.','Guarde seu código para recuperar o acesso neste navegador.')+`<code class="code">${e(s.recovery)}</code>`+notice('Este código substitui o envio por SMS nesta demonstração. Guarde-o fora do aplicativo. Se apagar os dados do navegador, a conta local também será apagada.')+`<div class="actions">${button('Baixar meu código de recuperação','download-recovery','secondary')}${button('Guardei o código. Continuar','finish-signup')}</div>`;
 case 'recover':return heading('Recupere<br>seu acesso.','Use o telefone e o código que recebeu ao criar sua conta neste navegador.')+`<form id="recover-form" novalidate>${formError()}${field('phone','Telefone cadastrado',{type:'tel',auto:'tel'})}${field('recovery','Código de recuperação',{placeholder:'SPM-…',auto:'off'})}${field('password','Nova senha',{type:'password',auto:'new-password',hint:'Use pelo menos 8 caracteres.'})}<div class="actions"><button class="button" type="submit">Salvar nova senha</button>${link('Voltar para entrar','login','secondary')}</div></form>`+notice('Não há envio de SMS. Sem o código, você pode explorar a demonstração ou criar outro cadastro com um telefone diferente.');
 case 'clinic':{
  const r=clinicResults(s.query,d);
  return step(1,'Clínica')+heading('Onde será<br>sua consulta?','Busque pelo nome da clínica ou pelo bairro.')+field('clinic-search','Nome ou bairro',{value:s.query,required:false,placeholder:'Digite um nome ou bairro'})+`<p class="results" id="results-count" role="status">${r.count} clínica${r.count===1?'':'s'} encontrada${r.count===1?'':'s'}</p><div id="clinic-results">${r.html}</div><div class="actions">${button('Continuar com esta clínica','next-clinic')}${s.changeId?button('Manter consulta atual','abort-change','secondary'):''}</div>`;
 }
 case 'specialty':return step(2,'Atendimento')+heading('Qual atendimento<br>você procura?','Escolha uma especialidade para ver os profissionais.')+context(clinic(d.clinicId).name)+`<div class="choices">${specialties.filter(x=>clinic(d.clinicId).specialties.includes(x.id)).map(x=>choice({id:x.id,name:x.name,sub:x.description,selected:d.specialtyId===x.id,action:'specialty'})).join('')}</div><div class="actions">${button('Ver profissionais','next-specialty')}</div>`;
 case 'professional':return step(2,'Atendimento')+heading('Com quem será<br>sua consulta?',`Profissionais de ${e(specialty(d.specialtyId).name)}.`)+context(clinic(d.clinicId).name)+`<div class="choices">${professionals.filter(p=>p.specialty===d.specialtyId&&p.clinics.includes(d.clinicId)).map(p=>{const date=dates().find(dt=>availableTimes(p.id,dt,s.allBookings).length);return choice({id:p.id,name:p.name,sub:'Atendimento presencial',meta:s.remote?'Consulte os horários na próxima etapa':date?`Próximo dia: ${dateLabel(date,true)}`:'Sem agenda no período',selected:d.professionalId===p.id,initials:p.initials,action:'professional'});}).join('')}</div><div class="actions">${button('Ver dias e horários','next-professional')}</div>`;
 case 'time':{
  const shown=dates().slice(s.dateOffset,s.dateOffset+3),slots=d.date?(s.remote?s.remoteSlots:availableTimes(d.professionalId,d.date,s.allBookings,s.changeId)):[];
  return step(3,'Horário')+heading(s.changeId?'Vamos mudar<br>o horário?':'Escolha o melhor<br>dia e horário.',`${e(professional(d.professionalId).name)} · ${e(specialty(d.specialtyId).name)}`)+(s.changeId?`<div class="booking-current"><span>HORÁRIO ATUAL</span><strong>${e(dateLabel(s.original.date,true))} · ${e(timeLabel(s.original.time))}</strong><p>Só muda depois de você confirmar.</p></div>`:'')+`<div class="date-heading"><h2>Dias de atendimento</h2><div class="date-pager"><button type="button" data-action="dates-prev" aria-label="Ver dias anteriores" ${s.dateOffset===0?'disabled':''}>${icon('back')}</button><button type="button" data-action="dates-next" aria-label="Ver próximos dias" ${s.dateOffset>=15?'disabled':''}>${icon('next')}</button></div></div><div class="dates">${shown.map(dt=>`<button class="date" type="button" data-action="date" data-id="${dt}" aria-label="${e(dateLabel(dt))}" aria-pressed="${d.date===dt}"><span>${dateObject(dt).toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','').toUpperCase()}</span><strong>${dateObject(dt).getDate()}</strong><span>${dateObject(dt).toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}</span>${d.date===dt?icon('check'):''}</button>`).join('')}</div><h2 class="time-heading">${d.date?'Horários disponíveis':'Escolha um dia para ver os horários'}</h2>${s.slotError?notice(e(s.slotError)):s.slotsLoading?'<p class="hint" role="status">Consultando os horários disponíveis…</p>':d.date?slots.length?`<div class="times">${slots.map(t=>`<button class="time" type="button" data-action="time" data-id="${t}" aria-pressed="${d.time===t}">${e(timeLabel(t))}${d.time===t?icon('check'):''}</button>`).join('')}</div>`:`<div class="empty"><span class="empty-symbol">${icon('calendar')}</span><h2>Este dia está sem horários.</h2><p>Escolha outro dia ou consulte outro profissional.</p><a class="row-link" href="#professional">Trocar profissional</a></div>`:''}${d.date&&d.time?notice(`Sua escolha: ${e(dateLabel(d.date,true))}, às ${e(timeLabel(d.time))}.`):''}<div class="actions">${button(s.changeId?'Revisar novo horário':d.time?`Continuar com ${e(timeLabel(d.time))}`:'Continuar','next-time')}${s.changeId?button('Manter consulta atual','abort-change','secondary'):''}</div>`;
 }
 case 'review':return step(4,'Revisão')+heading(s.changeId?'Confira a alteração.':'Está tudo certo?','Confira os dados antes de confirmar.')+(s.changeId?`<div class="booking-current"><span>ANTES</span><strong>${e(dateLabel(s.original.date,true))} · ${e(timeLabel(s.original.time))}</strong></div>`:'')+summary(d)+`<a class="row-link" href="#time">${icon('refresh')}Alterar dia ou horário</a>${!s.changeId?'<a class="row-link" href="#clinic">Alterar clínica ou atendimento</a>':''}${notice('Reserva apenas na agenda fictícia deste navegador. Não é uma consulta médica real.')}<div class="actions">${button(s.changeId?'Confirmar alteração':'Confirmar agendamento','confirm-booking')}${s.changeId?button('Manter consulta atual','abort-change','secondary'):''}</div>`;
 case 'success':return `<span class="success-icon">${icon('check')}</span><div class="eyebrow">TUDO PRONTO</div>`+heading(s.wasChange?'Seu horário<br>foi alterado.':'Sua consulta<br>está marcada.','Registro salvo na demonstração deste navegador.')+appointment(s.lastBooking)+context(clinic(s.lastBooking.clinicId).name)+`<div class="actions">${link('Ver minha consulta',`detail/${s.lastBooking.id}`)}${link('Voltar ao início','home','secondary')}</div>`;
 case 'appointments':{
  const now=new Date(),future=b=>b.status==='scheduled'&&new Date(`${b.date}T${b.time}`)>=now;
  const list=s.bookings.filter(b=>s.tab==='upcoming'?future(b):!future(b));
  return heading('Minhas<br>consultas.','Tudo organizado para você.')+`<div class="tabs" role="group" aria-label="Período das consultas"><button aria-pressed="${s.tab==='upcoming'}" data-action="tab" data-id="upcoming">Próximas</button><button aria-pressed="${s.tab==='history'}" data-action="tab" data-id="history">Histórico</button></div>${list.length?list.map(b=>`<section class="consultation"><div class="badge ${b.status==='cancelled'?'cancelled':''}">${icon(b.status==='cancelled'?'close':'check')}${b.status==='cancelled'?'Cancelada':future(b)?'Agendada':'Horário encerrado'}</div>${appointment(b)}<p class="place">${e(clinic(b.clinicId).name)}<span>${e(clinic(b.clinicId).district)}, Recife</span></p>${link('Ver detalhes',`detail/${b.id}`,'secondary')}</section>`).join(''):`<div class="empty"><span class="empty-symbol">${icon('calendar')}</span><h2>${s.tab==='upcoming'?'Nenhuma consulta por enquanto.':'Seu histórico ainda está vazio.'}</h2><p>${s.tab==='upcoming'?'Escolha um atendimento para fazer seu primeiro agendamento.':'Consultas canceladas e horários encerrados aparecem aqui.'}</p></div>`}<div class="actions">${button('Agendar outra consulta','new-booking','secondary')}</div>`;
 }
 case 'account':return heading('Sua conta.','Informações salvas neste navegador.')+`<div class="account-head"><span class="avatar">${e(u.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><div><h2>${e(u.name)}</h2><p class="hint">${u.demo?'Perfil de demonstração':e(u.phone)}</p></div></div><div class="account-list"><a href="#edit-profile">${icon('user')}Editar nome e nascimento</a><a href="#settings">${icon('text')}Ajustar leitura</a><a href="#install">${icon('download')}Instalar o aplicativo</a><button type="button" data-action="export-account">${icon('download')}Baixar meus dados</button><a href="#about">${icon('info')}Sobre o projeto</a><button type="button" data-action="logout">${icon('lock')}Sair desta conta</button><button type="button" data-action="delete-account">${icon('close')}Apagar esta conta local</button></div>`+notice('Os dados não são compartilhados entre dispositivos. Ao limpar o armazenamento do navegador, os cadastros e consultas locais podem ser apagados.');
 case 'edit-profile':return heading('Seus dados,<br>do seu jeito.','Atualize os dados da sua conta local.')+`<form id="profile-form" novalidate>${formError()}${field('name','Nome completo',{value:u.name,auto:'name'})}${field('birth','Data de nascimento',{type:'date',value:u.birth,auto:'bday',max:localISO()})}<div class="actions"><button class="button" type="submit">Salvar meus dados</button>${link('Voltar para a conta','account','secondary')}</div></form>`;
 case 'settings':return heading('Leitura do<br>seu jeito.','Ajuste como os textos aparecem para você.')+`<h2>Tamanho das letras</h2><div class="settings-options">${[['1','Padrão'],['1.15','Maior'],['1.3','Bem maior']].map(([v,label])=>`<button type="button" data-action="font" data-id="${v}" aria-pressed="${String(s.prefs.scale)===v}">${label}</button>`).join('')}</div><div class="sample"><small>PRÉVIA DO TEXTO</small><h2>Sua próxima consulta</h2><p>${e(dateLabel(dates()[0],true))}, às 10h.</p></div><div class="toggle-row"><label for="contrast">Contraste reforçado<small>Destaca textos e contornos.</small></label><input id="contrast" type="checkbox" ${s.prefs.contrast?'checked':''}></div>${notice('As mudanças são aplicadas e salvas automaticamente. As opções de acessibilidade do celular continuam disponíveis.')}<div class="actions">${button('Restaurar leitura padrão','reset-prefs','secondary')}${link('Voltar ao início',u?'home':'welcome')}</div>`;
 case 'install':return heading('Seu cuidado,<br>mais perto.','Adicione o aplicativo à tela inicial para abrir com facilidade.')+`<div class="help-section"><h2>Instalar neste dispositivo</h2><p>${s.installPrompt?'Seu navegador permite iniciar a instalação por aqui.':'Se a opção não aparecer aqui, use o menu do navegador para instalar ou adicionar à tela inicial.'}</p><div class="actions">${button('Instalar aplicativo','install','',s.installPrompt?'':'hidden')}${button('Conferir instalação e offline','check-pwa','secondary')}</div><div id="pwa-status" class="install-status" role="status"></div></div><div class="help-section"><h2>No iPhone ou iPad</h2><ol><li>Abra no Safari.</li><li>Toque em Compartilhar.</li><li>Escolha “Adicionar à Tela de Início”.</li></ol></div><div class="help-section"><h2>Para usar sem internet</h2><p>Abra o aplicativo uma vez com internet e aguarde a confirmação de que ele está pronto para uso offline. Cadastros e consultas da demonstração ficam neste navegador.</p></div>`;
 case 'about':return heading('Saúde na Palma<br>da Mão.','Um projeto acadêmico de agendamento acessível.')+`<div class="help-section"><h2>Para quem foi pensado</h2><p>Pessoas que querem marcar e acompanhar consultas com clareza, especialmente pessoas idosas.</p><h2>Conta online</h2><p>Cadastro, acesso por telefone e senha, recuperação por código, edição e exclusão de perfil, agendamento, reagendamento, cancelamento e histórico. Os dados da conta online ficam no servidor, em PostgreSQL no Supabase, e podem ser acessados em outro dispositivo após entrar na mesma conta.</p><h2>Demonstração local</h2><p>O botão Explorar demonstração abre um perfil fictício, com dados somente neste navegador. Esse modo continua funcionando sem internet após o primeiro acesso completo. Contas online precisam de conexão para acessar ou alterar registros.</p><h2>Agenda acadêmica</h2><p>Clínicas, profissionais, endereços e horários são fictícios. O aplicativo não reserva consultas médicas reais, não avalia sintomas e não envia SMS. Use dados fictícios para os exercícios.</p></div><div class="actions">${link('Abrir painel do projeto','dashboard','secondary')}${link('Instalar e verificar offline','install','secondary')}${link('Termos e privacidade','legal','text')}</div>`;
 case 'legal':return heading('Termos do<br>projeto acadêmico.','Leia antes de criar sua conta.')+`<div class="help-section"><h2>Finalidade acadêmica</h2><p>Esta aplicação demonstra o fluxo de agendamento. Não presta atendimento de saúde, faz diagnóstico ou confirma consultas em clínicas reais. Use dados fictícios no exercício.</p><h2>Dados da conta online</h2><p>Nome, telefone, nascimento e consultas são armazenados no banco PostgreSQL do projeto no Supabase. O backend está hospedado na Vercel. O telefone identifica a conta; não verificamos sua titularidade por SMS.</p><h2>Acesso e recuperação</h2><p>Senhas são derivadas com scrypt e sal aleatório. O código de recuperação e os identificadores de sessão são armazenados por hash. O acesso usa um cookie protegido, com validade de sete dias. A recuperação troca o código e encerra sessões anteriores.</p><h2>Controle dos seus registros</h2><p>Na conta, você pode editar nome e nascimento, exportar seus dados, sair ou excluir cadastro e consultas do servidor. A exclusão também encerra todas as sessões. Limpar o navegador encerra o acesso local, mas não apaga uma conta online.</p><h2>Demonstração local e acessibilidade</h2><p>O perfil de demonstração e as preferências de leitura ficam neste navegador. Dados antigos da versão local não são transferidos automaticamente ao servidor. O Service Worker guarda arquivos da interface; não armazena respostas privadas da API.</p><h2>Sem mensagens</h2><p>O aplicativo não envia SMS ou e-mails de recuperação. Guarde o código fornecido no cadastro em um lugar seguro.</p></div>${link('Voltar ao cadastro','register','secondary')}`;
 case 'dashboard':return dashboard(s);
 default:{
  if(s.route.startsWith('detail/')){
   const b=s.bookings.find(x=>x.id===s.route.split('/')[1]);
   if(!b)return heading('Consulta não encontrada.','Ela não está disponível nesta conta.')+link('Ver minhas consultas','appointments');
   const editable=b.status==='scheduled'&&new Date(`${b.date}T${b.time}`)>new Date();
   return `<div class="eyebrow">MINHAS CONSULTAS</div>`+heading(b.status==='cancelled'?'Consulta cancelada.':'Sua consulta.',b.status==='cancelled'?'O horário foi liberado na demonstração.':'Registro salvo neste navegador.')+summary(b)+context(`${clinic(b.clinicId).address} · ${clinic(b.clinicId).district}`)+`<div class="actions">${editable?button('Reagendar consulta','reschedule','',`data-id="${b.id}"`)+button('Cancelar consulta','cancel','danger',`data-id="${b.id}"`):''}${b.status==='scheduled'?button('Adicionar ao meu calendário','calendar','secondary',`data-id="${b.id}"`):''}${link('Voltar para minhas consultas','appointments','text')}</div>`;
  }
  return heading('Vamos voltar ao início?','Não encontramos essa página.')+link('Ir para o início',u?'home':'welcome');
 }
 }
}
export function filteredSessions(filters){
 const today=localISO(),cut=new Date();cut.setDate(cut.getDate()-Number(filters.period||30)+1);const start=localISO(cut);
 return syntheticSessions().filter(x=>x.date>=start&&x.date<=today&&(filters.age==='all'||x.ageGroup===filters.age)&&(filters.clinic==='all'||x.clinicId===filters.clinic));
}
function dashboard(s){
 const f=s.filters,rows=filteredSessions(f),total=rows.length,abandoned=rows.filter(x=>x.outcome==='abandono').length,rate=total?abandoned/total*100:0;
 const errors=rows.reduce((a,r)=>a+r.validationErrors,0),taps=rows.reduce((a,r)=>a+r.invalidTaps,0);
 const groups=['clinica','atendimento','horario','revisao'].map((id,i)=>({id,label:['Clínica','Atendimento','Horário','Revisão'][i],n:rows.filter(r=>r.step===id&&r.outcome==='abandono').length}));
 const max=Math.max(1,...groups.map(g=>g.n));
 const ages=['18–59','60+'].map(a=>{const r=rows.filter(x=>x.ageGroup===a),n=r.filter(x=>x.outcome==='abandono').length;return {age:a,n:r.length,abandon:n,rate:r.length?n/r.length*100:0};});
 const opt=(v,l,current)=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`;
 return `<div class="eyebrow">ÁREA DO PROJETO · CENÁRIO SINTÉTICO</div>`+heading('Onde o agendamento<br>precisa de atenção?','Painel para o responsável pelo serviço priorizar melhorias no percurso.')+notice('Os indicadores abaixo usam 180 sessões sintéticas, criadas para demonstrar os cálculos. Não são as 45.230 sessões citadas na apresentação anterior.')+`<form id="dashboard-filters" class="filters"><div class="field"><label for="period">Período</label><select id="period" name="period">${opt('7','Últimos 7 dias',f.period)}${opt('14','Últimos 14 dias',f.period)}${opt('30','Últimos 30 dias',f.period)}</select></div><div class="field"><label for="age">Faixa etária</label><select id="age" name="age">${opt('all','Todas',f.age)}${opt('18–59','18 a 59 anos',f.age)}${opt('60+','60 anos ou mais',f.age)}</select></div><div class="field"><label for="clinic-filter">Clínica</label><select id="clinic-filter" name="clinic">${opt('all','Todas as clínicas',f.clinic)}${clinics.map(c=>opt(c.id,e(c.name),f.clinic)).join('')}</select></div></form><div class="stats" aria-live="polite"><div class="stat"><small>Sessões no recorte</small><strong>${total}</strong><span>unidade: sessão</span></div><div class="stat"><small>Taxa de abandono</small><strong>${rate.toFixed(1).replace('.',',')}%</strong><span>${abandoned} de ${total} sessões</span></div><div class="stat"><small>Erros de validação</small><strong>${errors}</strong><span>${total?(errors/total).toFixed(2).replace('.',','):'0'} por sessão</span></div></div><div class="dashboard-grid"><section><h2>Em qual etapa há mais abandono?</h2><div class="chart">${groups.map(g=>`<div class="bar-row"><span>${g.label}</span><span class="bar-track" aria-hidden="true"><i style="width:${g.n/max*100}%"></i></span><b>${g.n}</b></div>`).join('')}</div><p class="hint">Sessões encerradas sem concluir, agrupadas pela última etapa. Contagens, não taxas por etapa.</p></section><section><h2>Como o abandono varia com a idade?</h2><div class="table-wrap"><table><thead><tr><th>Faixa</th><th>Sessões</th><th>Abandono</th></tr></thead><tbody>${ages.map(a=>`<tr><td>${a.age} anos</td><td>${a.n}</td><td>${ratioLabel(a.abandon,a.n)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Pessoas de exatamente 60 anos pertencem ao grupo 60+. A comparação descreve este cenário simulado.</p></section><section><h2>Quais falhas precisam de investigação?</h2><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Total</th><th>Por sessão</th></tr></thead><tbody><tr><td>Erros de validação</td><td>${errors}</td><td>${total?(errors/total).toFixed(2):'0'}</td></tr><tr><td>Toques inválidos</td><td>${taps}</td><td>${total?(taps/total).toFixed(2):'0'}</td></tr></tbody></table></div></section><section><h2>Que decisão este painel apoia?</h2><p>Priorizar a etapa com mais encerramentos e revisar linguagem, campos e alvos de toque. Os dados simulados não demonstram causas nem resultados em pacientes reais.</p></section></div><p class="data-source"><strong>Fonte:</strong> cenário sintético acadêmico gerado no aplicativo. Uma linha = uma sessão. Origem e período acompanham a exportação. Taxa de abandono = sessões com abandono ÷ sessões do recorte × 100.</p><div class="actions inline">${button('Baixar a base deste recorte (CSV)','export-csv','secondary')}${button('Baixar dicionário de dados','export-dictionary','secondary')}</div><div class="help-section separated"><h2>Ações realizadas neste navegador</h2><p>${s.allBookings.length} consulta(s) registrada(s), ${s.allBookings.filter(x=>x.status==='cancelled').length} cancelada(s). Esses registros locais são separados das sessões sintéticas do painel.</p></div><div class="about-links"><a href="#home">Voltar para o aplicativo</a><a href="#about">Sobre os dados</a></div>`;
}

export function view(s){
 let html=baseView(s);
 if(!s.remote)return html;
 const copies=[
  ['Criar uma conta neste navegador','Criar minha conta online'],
  ['Seus dados ficam neste navegador.','Contas online usam dados salvos no servidor.'],
  ['Conta salva neste navegador.','Conta online com dados salvos no servidor.'],
  ['Use o telefone e a senha cadastrados neste navegador.','Use o telefone e a senha da sua conta online.'],
  ['O cadastro funciona neste navegador, inclusive sem internet.','Seus dados ficam na sua conta online. Você precisa de internet para criar o cadastro.'],
  ['Guarde seu código para recuperar o acesso neste navegador.','Guarde seu código para recuperar o acesso à conta online.'],
  ['Este código substitui o envio por SMS nesta demonstração. Guarde-o fora do aplicativo. Se apagar os dados do navegador, a conta local também será apagada.','Guarde este código fora do aplicativo. Não há envio de SMS. Quando usar o código, ele será substituído e as sessões anteriores serão encerradas.'],
  ['Use o telefone e o código que recebeu ao criar sua conta neste navegador.','Use o telefone e o código fornecido no cadastro da sua conta online.'],
  ['Reserva apenas na agenda fictícia deste navegador. Não é uma consulta médica real.','Reserva na agenda acadêmica compartilhada do servidor. Não é uma consulta médica real.'],
  ['Registro salvo na demonstração deste navegador.','Registro salvo na sua conta online.'],
  ['Informações salvas neste navegador.','Informações da sua conta online.'],
  ['Apagar esta conta local','Apagar minha conta online'],
  ['Os dados não são compartilhados entre dispositivos. Ao limpar o armazenamento do navegador, os cadastros e consultas locais podem ser apagados.','Entre com o mesmo telefone e senha em outro dispositivo para acessar suas consultas. Seus registros ficam no servidor até você excluir a conta.'],
  ['Atualize os dados da sua conta local.','Atualize os dados da sua conta online.'],
  ['Registro salvo neste navegador.','Registro salvo no servidor.'],
  ['Ações realizadas neste navegador','Registros da conta atual'],
  ['Esses registros locais são separados das sessões sintéticas do painel.','Esses registros da sua conta são separados das sessões sintéticas do painel.']
 ];
 for(const [from,to] of copies)html=html.replaceAll(from,to);
 return html;
}
